WITH valid AS (SELECT *, CASE WHEN dept_name = 'HR' THEN 1 ELSE 0 END AS is_hr, LENGTH(location) AS location_length, COALESCE(location, 'UNKNOWN') AS resolved_location FROM departments WHERE location IN ('Bangkok', 'London')) SELECT id, dept_name, location, budget, is_hr, location_length FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY location ORDER BY budget ASC, id ASC) AS rank_in_group FROM valid) x WHERE rank_in_group = 1
